#pragma once
namespace nido {
constexpr char kMaintenancePage[] = R"HTML(<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Nido · mantenimiento</title><style>body{font:17px system-ui;max-width:34rem;margin:2rem auto;padding:0 1rem;color:#242824;background:#faf9f5}label{display:block;margin-top:1rem}input,button,select{font:inherit;padding:.6rem;max-width:100%;box-sizing:border-box}input{width:100%}button{margin-top:1rem}section{border-top:1px solid #ccc;margin-top:2rem}#message{white-space:pre-wrap}small{display:block}</style><h1>Nido</h1><p>Configuración y mantenimiento del Note4</p><p id="status"></p><section><h2>Conectar a Wi-Fi</h2><form id="config"><label>Red Wi-Fi (2,4 GHz)<input name="ssid" list="networks" maxlength="32" required autocomplete="off"></label><datalist id="networks"></datalist><button id="scan" type="button">Buscar redes</button><label>Contraseña Wi-Fi<input name="password" type="password" maxlength="63" autocomplete="new-password"></label><button>Comprobar y guardar Wi-Fi</button></form></section><section><h2>Vincular con Nido</h2><p>Después de guardar la Wi-Fi, vuelve a tu red de casa y abre los ajustes del plugin de Nido. Pulsa «Buscar Note4» e introduce el código que aparece en la pantalla del dispositivo.</p><button id="pair-code">Mostrar código de vinculación</button></section><section><h2>Actualizar firmware</h2><label>Archivo firmado .nidoota<input id="firmware" type="file" accept=".nidoota"></label><button id="update">Instalar actualización</button><p>Conecta el Note4 a la alimentación durante la actualización.</p></section><p id="message" role="status"></p><button id="exit">Salir de mantenimiento</button><script>
const session='__SESSION__';const message=document.querySelector('#message');
async function request(path,body){const r=await fetch(path,{method:body===undefined?'GET':'POST',headers:{'X-Nido-Session':session,'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const v=await r.json();if(!r.ok)throw Error(v.error||'No se pudo completar');return v;}
function status(){return request('/status').then(v=>document.querySelector('#status').textContent='Versión: '+v.version+' · '+(v.configured?'Vinculado con Nido':v.wifiConfigured?'Wi-Fi guardada · Nido sin vincular':'Wi-Fi sin configurar')).catch(e=>message.textContent=e.message);}status();
document.querySelector('#scan').onclick=async()=>{try{message.textContent='Buscando redes…';const result=await request('/networks');const list=document.querySelector('#networks');list.replaceChildren();for(const network of result.networks){const option=document.createElement('option');option.value=network.ssid;list.appendChild(option);}message.textContent='Elige una red o escribe su nombre.';}catch(e){message.textContent=e.message;}};
document.querySelector('#config').onsubmit=async e=>{e.preventDefault();try{message.textContent='Comprobando Wi-Fi…';const form=new FormData(e.target);const result=await request('/configure',{ssid:form.get('ssid'),password:form.get('password')});message.textContent=result.message;await status();}catch(e){message.textContent=e.message;}};
document.querySelector('#pair-code').onclick=()=>request('/pair/start',{}).then(v=>message.textContent=v.message).catch(e=>message.textContent=e.message);
document.querySelector('#update').onclick=async()=>{const f=document.querySelector('#firmware').files[0];if(!f)return; if(!confirm('¿Instalar este firmware y reiniciar el Note4?'))return;try{message.textContent='Transfiriendo y verificando…';const r=await fetch('/firmware',{method:'POST',headers:{'X-Nido-Session':session,'Content-Type':'application/octet-stream'},body:f});const v=await r.json();if(!r.ok)throw Error(v.error);message.textContent='Firmware verificado. Reiniciando…';}catch(e){message.textContent=e.message;}};
document.querySelector('#exit').onclick=()=>request('/exit',{}).then(()=>message.textContent='Punto de acceso cerrado. Puedes volver al Wi-Fi de casa.').catch(e=>message.textContent=e.message);
</script></html>)HTML";
}
